<template>
  <div><PageHeader eyebrow="LEARNING" title="Tiến độ" description="Tiến độ bài học và hoạt động được đọc từ các projection dành cho workspace hiện tại." /><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><div class="toolbar"><select v-model="selectedClassId" class="form-select" style="max-width:340px"><option value="">Chọn lớp học</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select><span class="cell-subtle">{{ progressPercent }}% hoàn thành</span></div><div v-if="loading" class="loading-state">Đang tải tiến độ…</div><template v-else-if="selectedClassId && courseProgress"><div class="metrics-grid"><MetricCard icon="✓" label="Bài học hoàn thành" :value="`${completedLessons}/${totalLessons}`" hint="Theo lớp đang chọn" /><MetricCard icon="↗" label="Tiến độ khóa học" :value="`${progressPercent}%`" hint="Projection hiện tại" /><MetricCard icon="▤" label="Hoạt động" :value="activityEntries.length" hint="Có trạng thái học tập" /><MetricCard icon="◷" label="Cập nhật" :value="formatDateTime(lastUpdated)" hint="Thời gian gần nhất" /></div><section class="panel"><div class="panel-heading"><h2>Lesson progress</h2><span>{{ lessonEntries.length }} bản ghi</span></div><div v-if="lessonEntries.length" class="list-compact"><div v-for="entry in lessonEntries" :key="`${entry.studentId}-${entry.lessonId}`" class="list-compact-item"><div><strong>{{ entry.lessonTitle }}</strong><span>{{ enumLabel(entry.status) }} · {{ entry.updatedAt ? formatDateTime(entry.updatedAt) : 'Chưa bắt đầu' }}</span></div><StatusPill :value="entry.status" /></div></div><div v-else class="empty-state"><strong>Chưa có dữ liệu bài học</strong><span>Tiến độ sẽ được ghi nhận khi người học mở và hoàn thành bài.</span></div></section><section class="panel"><div class="panel-heading"><h2>Activity progress</h2><span>{{ activityEntries.length }} hoạt động</span></div><div v-if="activityEntries.length" class="list-compact"><div v-for="entry in activityEntries" :key="`${entry.studentId}-${entry.activityId}`" class="list-compact-item"><div><strong>{{ entry.activityTitle }}</strong><span>{{ entry.score }}/{{ entry.maxScore }} · {{ entry.completion }}%</span></div><StatusPill :value="entry.status" /></div></div><div v-else class="empty-state"><strong>Chưa có activity progress</strong><span>Hoạt động hoàn thành sẽ hiển thị tại đây.</span></div></section></template><div v-else class="panel empty-state"><strong>Chọn lớp học</strong><span>Chọn lớp để xem tiến độ chi tiết.</span></div></div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import PageHeader from '../../../shared/ui/PageHeader.vue'; import MetricCard from '../../../shared/ui/MetricCard.vue'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import { academicsApi, learningApi } from '../../../shared/api/client'; import { enumLabel, formatDateTime, type LearningClass } from '../../../shared/types'; import { useAuthStore } from '../../../shared/stores/auth'
type LessonEntry = { studentId: string; lessonId: string; lessonTitle: string; status?: string | number; updatedAt?: string }; type ActivityEntry = { studentId: string; activityId: string; activityTitle: string; score: number; maxScore: number; completion: number; status?: string | number; completedAt?: string }
const auth = useAuthStore(); const classes = ref<LearningClass[]>([]); const selectedClassId = ref(''); const courseProgress = ref<{ totalLessons?: number; entries?: LessonEntry[]; completionPercent?: number } | null>(null); const loading = ref(true); const error = ref(''); const lessonEntries = computed(() => courseProgress.value?.entries || []); const activityEntries = ref<ActivityEntry[]>([]); const totalLessons = computed(() => courseProgress.value?.totalLessons || lessonEntries.value.length); const completedLessons = computed(() => lessonEntries.value.filter(item => String(item.status).toLowerCase().includes('complete') || item.status === 2).length); const progressPercent = computed(() => Math.round(Number(courseProgress.value?.completionPercent || (totalLessons.value ? completedLessons.value / totalLessons.value * 100 : 0)))); const lastUpdated = computed(() => lessonEntries.value.map(item => item.updatedAt).filter(Boolean).sort().at(-1))
async function load() { if (!selectedClassId.value) { courseProgress.value = null; loading.value = false; return }; loading.value = true; try { const result = await learningApi.courseProgress(selectedClassId.value, auth.role === 'student'); courseProgress.value = result as typeof courseProgress.value; const own = auth.role === 'student' ? await learningApi.myProgress(selectedClassId.value) : await learningApi.classProgress(selectedClassId.value); activityEntries.value = (own.entries || []) as ActivityEntry[] } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được tiến độ.') } finally { loading.value = false } }
async function boot() { try { classes.value = await academicsApi.classes(); if (classes.value[0]) selectedClassId.value = classes.value[0].id } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được lớp học.'); loading.value = false } }; watch(selectedClassId, load); onMounted(boot)
</script>
